import { computed, inject, onBeforeUnmount, provide, watch, type ComputedRef, type InjectionKey } from 'vue'
import { useFullscreen, type UseFullscreenReturn } from 'vue-fullscreen'

/**
 * 组件预览区全屏：全屏能力由 vue-fullscreen 提供（Vue 3 对应 5.x）。
 *
 * demo 里固定使用 pageOnly + teleport 模式：不调用浏览器原生 Fullscreen API，
 * 而是把预览区临时挂到 body、用 fixed 定位铺满视口；这样在 iframe / 内嵌页面里
 * 也能用，退出时再还原到页面原来的位置。
 */
export interface DemoFullscreen extends UseFullscreenReturn {
  /** pageOnly 模式不依赖浏览器原生全屏能力，iframe 内也能用，恒为 true */
  isSupported: ComputedRef<boolean>
  /** 当前页面有没有可全屏的组件预览区（简介页没有） */
  hasTarget(): boolean
}

const DEMO_FULLSCREEN_KEY: InjectionKey<DemoFullscreen> = Symbol('demo-fullscreen')

/**
 * 在 App 里创建唯一一份全屏控制器，工具栏按钮与预览区的「退出全屏」按钮通过
 * `useDemoFullscreen()` 共用它，这样两边的全屏状态才是同一份。
 */
export function provideDemoFullscreen(resolveTarget: () => Element | null): DemoFullscreen {
  const controller = useFullscreen(resolveTarget, {
    pageOnly: true,
    teleport: true,
    fullscreenClass: 'is-demo-fullscreen',
  })

  let previousBodyOverflow = ''
  let bodyLocked = false

  function lockBodyScroll() {
    if (bodyLocked) return
    previousBodyOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    bodyLocked = true
  }

  function unlockBodyScroll() {
    if (!bodyLocked) return
    document.body.style.overflow = previousBodyOverflow
    bodyLocked = false
  }

  // 预览区铺满视口时锁住 body 滚动，退出时恢复（Esc 退出同样会走到这里）
  watch(controller.isFullscreen, (value) => {
    if (value) lockBodyScroll()
    else unlockBodyScroll()
  })
  onBeforeUnmount(unlockBodyScroll)

  const api: DemoFullscreen = {
    ...controller,
    isSupported: computed(() => true),
    hasTarget: () => Boolean(resolveTarget()),
  }

  provide(DEMO_FULLSCREEN_KEY, api)
  return api
}

export function useDemoFullscreen(): DemoFullscreen {
  const api = inject(DEMO_FULLSCREEN_KEY, null)
  if (!api) {
    throw new Error('useDemoFullscreen() 必须在调用了 provideDemoFullscreen() 的组件内使用')
  }
  return api
}
