import exampleTemplate from '../templates/hel-micro-cdn.html?raw'

/**
 * 「下载示例」页面生成器。
 *
 * 把 `src/templates/hel-micro-cdn.html` 这个单文件示例模板 + 当前示例的组件名 / 参数，
 * 拼成一份可以直接双击打开的 HTML：Vue 与 hel-micro 走 CDN，组件由 preFetchLib 在
 * 运行时从 unpkg 拉取，宿主（demo 产物）里并没有它的实现。
 *
 * 之所以在构建期用 `?raw` 内联模板、下载时再拼字符串，而不是 fetch 一个静态文件：
 * 这样不依赖网络、也不受 demo 的 `base` 路径影响，`file://` 下打开 demo 也能下载。
 */

/** 示例页引用的 hel-micro 版本，与 demo-vue3/package.json 保持一致 */
const HEL_MICRO_VERSION = '4.15.3'
/** 示例页引用的 Vue 全局构建版本，与远程组件 external 的版本保持一致 */
const VUE_VERSION = '3.5.45'

/** 远程组件包的 hel 组名（同 configs/remote.ts 的 REMOTE_LIB_NAME） */
const REMOTE_LIB_NAME = 'comps-vue3'
/** 远程组件包的元数据地址（同 configs/remote.ts 的 UNPKG_HOST） */
const REMOTE_META_URL = 'https://unpkg.com/@melt-js/comps-vue3/hel_dist/hel-meta.json'

/** 一个示例页对应的下载内容 */
export interface DownloadExample {
  /** comps-vue3 导出的组件名，如 CircularMenu */
  component: string
  /** 传给组件的参数，与示例页上的主展示保持一致 */
  props?: Record<string, unknown>
  /** 默认插槽的 HTML，有的组件靠插槽出内容 */
  slotHtml?: string
  /** 预览区背景，深色组件沿用示例页的底色 */
  background?: string
}

/** 组装下载文件：文件名 + 内容 */
export interface DownloadFile {
  fileName: string
  html: string
}

/** 用 split/join 替换占位符，避免 `$&` 这类替义字符被 String#replace 解释掉 */
function fill(template: string, token: string, value: string) {
  return template.split(token).join(value)
}

function escapeHtml(text: string) {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

/** CircularMenu -> circular-menu，用来拼下载文件名 */
function kebabCase(name: string) {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()
}

/** 示例页里那段真实运行的脚本；同一份文本既写进 <script>，也展示在页面的代码块里 */
function buildSnippet(example: DownloadExample) {
  const lines = [
    `import { preFetchLib } from 'https://esm.sh/hel-micro@${HEL_MICRO_VERSION}'`,
    '',
    'const { createApp, h } = Vue',
    '',
    '// 组名 + 组件包的元数据地址：换版本只改这一行',
    `const lib = await preFetchLib('${REMOTE_LIB_NAME}', {`,
    '  custom: {',
    `    host: '${REMOTE_META_URL}',`,
    '  },',
    '})',
    '',
    '// 示例参数来自页面里的 #demo-props，换成自己的数据即可',
    "const props = JSON.parse(document.getElementById('demo-props').textContent)",
  ]

  if (example.slotHtml) {
    lines.push(
      '',
      '// 示例插槽也来自页面里的 #demo-slot，换成自己的内容即可',
      "const slot = document.getElementById('demo-slot')?.innerHTML ?? ''",
    )
  }

  lines.push(
    '',
    '// 拿到的就是普通 Vue 组件',
    'createApp({',
    example.slotHtml
      ? `  render: () => h(lib.${example.component}, props, { default: () => h('div', { innerHTML: slot }) }),`
      : `  render: () => h(lib.${example.component}, props),`,
    "}).mount('#app')",
  )

  return lines.join('\n')
}

/** 把模板里的占位符换成当前示例的内容 */
export function buildDownloadFile(example: DownloadExample): DownloadFile {
  const propsJson = JSON.stringify(example.props ?? {}, null, 2)
  const snippet = buildSnippet(example)
  const slotTemplate = example.slotHtml
    ? `\n      <template id="demo-slot">${example.slotHtml}</template>`
    : ''

  let html = exampleTemplate
  html = fill(html, '__PAGE_TITLE__', `${example.component} · hel-micro html + cdn 示例`)
  html = fill(html, '__COMPONENT__', example.component)
  html = fill(html, '__VUE_VERSION__', VUE_VERSION)
  html = fill(html, '__STAGE_CLASS__', example.background ? 'stage is-dark' : 'stage')
  html = fill(
    html,
    '__STAGE_STYLE__',
    example.background ? ` style="background: ${example.background}"` : '',
  )
  html = fill(html, '__SNIPPET__', escapeHtml(snippet))
  html = fill(html, '__PROPS_JSON__', escapeHtml(propsJson))
  html = fill(html, '__SLOT_TEMPLATE__', slotTemplate)
  html = fill(html, '__SCRIPT__', snippet)

  return {
    fileName: `hel-micro-${kebabCase(example.component)}.html`,
    html,
  }
}
