<template>
  <header class="demo-navbar">
    <div class="demo-navbar__inner">
      <div class="demo-navbar__brand">
        <span class="demo-navbar__badge">{{ badge }}</span>
        <div>
          <p class="demo-navbar__title">{{ title }}</p>
          <p class="demo-navbar__sub">{{ subtitle }}</p>
        </div>
      </div>

      <nav class="demo-navbar__nav" aria-label="示例导航">
        <router-link
          v-for="item in navItems"
          :key="item.path"
          :to="item.path"
          class="demo-nav__link"
          :class="{ 'is-active': isActive(item.path) }"
          :title="item.description"
        >
          {{ item.title }}
        </router-link>
      </nav>
    </div>

    <!-- 简介行：随当前示例切换，说明这个示例在演示什么 -->
    <div class="demo-navbar__intro">
      <span class="demo-navbar__intro-tag">
        {{ currentTitle }} · {{ activeIndex + 1 }}/{{ navItems.length }}
      </span>
      <p class="demo-navbar__intro-text">{{ currentDescription }}</p>
    </div>
  </header>
</template>

<script setup lang="ts">
import { computed } from 'vue'
import { useRoute } from 'vue-router'
import { demoRoutes } from '../router'

/**
 * 顶部导航栏：品牌区 + 示例切换 tab + 当前示例简介。
 * 示例清单直接来自 router 的 meta（title / description），新增示例只需加一条路由。
 */
const props = defineProps<{
  title: string
  subtitle?: string
  badge?: string
}>()

const route = useRoute()

const navItems = computed(() =>
  demoRoutes
    .filter((item) => Boolean(item.meta?.title))
    .map((item) => ({
      path: item.path,
      title: String(item.meta?.title ?? ''),
      description: String(item.meta?.description ?? ''),
    })),
)

const activeIndex = computed(() => {
  const index = navItems.value.findIndex((item) => item.path === route.path)
  return index === -1 ? 0 : index
})

const currentTitle = computed(() => String(route.meta.title ?? props.title))
const currentDescription = computed(() => String(route.meta.description ?? ''))

function isActive(path: string) {
  return route.path === path
}
</script>
