<template>
  <button
    ref="buttonEl"
    type="button"
    class="screenfull-btn"
    :class="{ 'is-fullscreen': isFullscreen, 'is-disabled': !isSupported }"
    :title="tooltipText"
    :aria-label="tooltipText"
    :aria-pressed="isFullscreen ? 'true' : 'false'"
    :aria-disabled="isSupported ? 'false' : 'true'"
    @click="toggle"
  >
    <svg
      class="screenfull-btn__icon"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      stroke-width="2"
      stroke-linecap="round"
      stroke-linejoin="round"
      aria-hidden="true"
      focusable="false"
    >
      <path
        v-if="isFullscreen"
        d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3"
      />
      <path
        v-else
        d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"
      />
    </svg>
    <span v-if="showText" class="screenfull-btn__text">{{ buttonText }}</span>
  </button>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useDemoFullscreen } from '../composables/useDemoFullscreen'

/**
 * 组件预览区全屏按钮。
 *
 * 全屏能力由 vue-fullscreen 提供（Vue 3 对应 5.x）。demo 里固定使用
 * pageOnly + teleport 模式：不调用浏览器原生 Fullscreen API，而是把预览区
 * 临时挂到 body、用 fixed 定位铺满视口；这样在 iframe / 内嵌页面里也能用，
 * 退出时再还原到页面原来的位置。
 *
 * 全屏目标由 App 里的 `provideDemoFullscreen()` 统一提供，所以本组件不需要
 * target 参数；预览区里的「退出全屏」按钮复用同一份控制器。
 */
const props = withDefaults(
  defineProps<{
    enterText?: string
    exitText?: string
    unsupportedText?: string
    showText?: boolean
  }>(),
  {
    enterText: '全屏',
    exitText: '退出全屏',
    unsupportedText: '当前浏览器不支持全屏',
    showText: true,
  },
)

const emit = defineEmits<{
  (event: 'change', isFullscreen: boolean): void
  (event: 'error', message: string): void
}>()

const { isFullscreen, isSupported, enter, exit, hasTarget } = useDemoFullscreen()
const buttonEl = ref<HTMLButtonElement | null>(null)

const buttonText = computed(() => (isFullscreen.value ? props.exitText : props.enterText))
const tooltipText = computed(() => (isSupported.value ? buttonText.value : props.unsupportedText))

function notify(message: string) {
  // demo 没有引入 UI 库，只打印警告并把错误抛给使用方
  console.warn(`[Fullscreen] ${message}`)
  emit('error', message)
}

function restoreTriggerFocus() {
  // 退出时如果焦点还留在预览区（或被隐藏的「退出全屏」按钮上），还给工具栏按钮
  const preview = document.querySelector('.demo-preview')
  const active = document.activeElement
  if (active === document.body || (preview && active && preview.contains(active))) {
    buttonEl.value?.focus({ preventScroll: true })
  }
}

async function toggle() {
  // 先判断是否已经处于全屏：teleport 后预览区不在原位置，
  // 不能再通过 querySelector 去找它
  if (isFullscreen.value) {
    try {
      await exit()
    } catch (error) {
      console.warn('[Fullscreen] Failed to exit fullscreen:', error)
      notify('退出全屏失败，请稍后重试')
    }
    return
  }

  if (!hasTarget()) {
    notify('没有找到需要全屏的组件预览区')
    return
  }

  try {
    await enter()
  } catch (error) {
    console.warn('[Fullscreen] Failed to enter fullscreen:', error)
    notify('全屏切换失败，请稍后重试')
  }
}

watch(isFullscreen, (value) => {
  emit('change', value)
  if (!value) restoreTriggerFocus()
})
</script>
