<template>
  <button
    type="button"
    class="download-btn"
    :class="{ 'is-done': downloaded }"
    :title="tooltipText"
    :aria-label="tooltipText"
    @click="downloadExample"
  >
    <svg
      class="download-btn__icon"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      stroke-width="2"
      stroke-linecap="round"
      stroke-linejoin="round"
      aria-hidden="true"
      focusable="false"
    >
      <path v-if="downloaded" d="m4.5 12.75 6 6 9-13.5" />
      <path
        v-else
        d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M16.5 12 12 16.5m0 0L7.5 12m4.5 4.5V3"
      />
    </svg>
    <span class="download-btn__text">{{ buttonText }}</span>
  </button>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { DOWNLOAD_EXAMPLES, FALLBACK_EXAMPLE } from '../configs/downloadExamples'
import { buildDownloadFile } from '../configs/downloadPage'

/**
 * 下载「HTML + CDN」示例按钮，放在工具栏全屏按钮左侧。
 *
 * 下载的内容跟着当前示例页走：每个示例页对应的远程组件与参数登记在
 * `configs/downloadExamples.ts`，`configs/downloadPage.ts` 把模板拼成一份单文件
 * HTML（Vue 与 hel-micro 走 CDN，组件由 `preFetchLib` 在运行时从 unpkg 拉取）。
 * 简介 / 主应用这类没有远程组件的页面，下载一份 HelloWorld 快速上手示例。
 */
/** 「已下载」提示的展示时长 */
const DONE_RESET_DELAY = 2000

const route = useRoute()
const example = computed(() => DOWNLOAD_EXAMPLES[route.path] ?? FALLBACK_EXAMPLE)

const downloaded = ref(false)
const downloadedFile = ref('')
let resetTimer: ReturnType<typeof setTimeout> | undefined

const buttonText = computed(() => (downloaded.value ? '已下载' : '下载示例'))
const tooltipText = computed(() =>
  downloaded.value
    ? `已保存为 ${downloadedFile.value}`
    : `下载「${example.value.component}」示例（HTML + CDN 单文件，双击即可打开）`,
)

function clearResetTimer() {
  if (resetTimer) {
    clearTimeout(resetTimer)
    resetTimer = undefined
  }
}

function downloadExample() {
  let objectUrl = ''

  try {
    const { fileName, html } = buildDownloadFile(example.value)
    const blob = new Blob([html], { type: 'text/html;charset=utf-8' })
    objectUrl = URL.createObjectURL(blob)

    const link = document.createElement('a')
    link.href = objectUrl
    link.download = fileName
    link.rel = 'noopener'
    document.body.appendChild(link)
    link.click()
    link.remove()

    downloadedFile.value = fileName
  } catch (error) {
    console.warn('[Download] 生成示例 HTML 失败:', error)
    if (objectUrl) URL.revokeObjectURL(objectUrl)
    return
  }

  // 立即 revoke 会让部分浏览器拿不到内容，等下载任务接手后再释放
  setTimeout(() => URL.revokeObjectURL(objectUrl), 1000)

  downloaded.value = true
  clearResetTimer()
  resetTimer = setTimeout(() => {
    downloaded.value = false
    resetTimer = undefined
  }, DONE_RESET_DELAY)
}

// 切换示例后把「已下载」状态收回去，避免下一个页面的按钮还亮着
watch(
  () => route.path,
  () => {
    downloaded.value = false
    clearResetTimer()
  },
)

onBeforeUnmount(clearResetTimer)
</script>
