/**
 * 示例参数里的占位图：内联 SVG 渐变，不依赖外网图片。
 *
 * 「下载示例」会把各示例页里生成的渐变底图换成这里的 `tile(seed)`，
 * 这样导出的 HTML 仍然是单文件、离线可看。
 */
const PALETTE = [
  ['%236366f1', '%23ec4899'],
  ['%230ea5e9', '%2322d3ee'],
  ['%23f59e0b', '%23ef4444'],
  ['%2310b981', '%236366f1'],
  ['%238b5cf6', '%2322d3ee'],
  ['%23f472b6', '%23f59e0b'],
  ['%2314b8a6', '%230ea5e9'],
  ['%23facc15', '%23f97316'],
]

/** 生成一张 4:3 的双色渐变占位图（data URI） */
export function tile(seed: number) {
  const [from, to] = PALETTE[seed % PALETTE.length]
  const svg =
    `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 4 3'>` +
    `<linearGradient id='g' x2='1' y2='1'>` +
    `<stop stop-color='${from}'/>` +
    `<stop offset='1' stop-color='${to}'/>` +
    `</linearGradient>` +
    `<rect width='4' height='3' fill='url(%23g)'/>` +
    `</svg>`

  return `data:image/svg+xml;utf8,${svg}`
}
