<template>
  <div class="demo-app">
    <DemoNavbar :title="APP_META.name" :badge="APP_META.badge" :subtitle="APP_META.subtitle" />

    <main ref="stageEl" class="demo-stage">
      <div class="demo-stage__toolbar">
        <span class="demo-stage__hint">示例预览 <em>/</em> {{ currentTitle }}</span>
        <div class="demo-stage__actions">
          <DownloadExampleButton />
          <ScreenfullButton v-if="supportsFullscreen" />
        </div>
      </div>

      <div class="demo-stage__page">
        <router-view v-slot="{ Component }">
          <transition name="demo-fade" mode="out-in">
            <component :is="Component" :key="$route.path" />
          </transition>
        </router-view>
      </div>
    </main>

    <footer class="demo-footer">
      <span>{{ APP_META.name }} · hel-micro 消费方示例</span>
      <span>hash 路由，可直接从 unpkg 的 dist/index.html 打开</span>
    </footer>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import DemoNavbar from './components/DemoNavbar.vue'
import DownloadExampleButton from './components/DownloadExampleButton.vue'
import ScreenfullButton from './components/ScreenfullButton.vue'
import { provideDemoFullscreen } from './composables/useDemoFullscreen'
import { APP_META } from './configs/app'

const route = useRoute()
const stageEl = ref<HTMLElement | null>(null)

const currentTitle = computed(() => String(route.meta.title ?? ''))

// 简介页没有组件预览区，不显示全屏按钮
const supportsFullscreen = computed(() => route.meta.fullscreen !== false)

// 只把当前示例的组件预览区（DemoPreview 渲染的 data-demo-preview）送进全屏；
// 页面标题、简介、说明与页脚都在预览区之外，因此不会出现在全屏里
const fullscreen = provideDemoFullscreen(
  () => stageEl.value?.querySelector('[data-demo-preview]') ?? null,
)

watch(
  () => route.path,
  () => {
    // pageOnly + teleport 模式下预览区被临时移到 body，必须在旧页面卸载前还原；
    // 默认的 pre flush 会在组件重新渲染前执行，不能用 nextTick
    if (fullscreen.isFullscreen.value) {
      fullscreen.exit().catch(() => {})
    }
  },
)
</script>
